/**
 * Appear: animates the object into place once, when the game starts.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { Ticker } from "pixi.js";
import { Component, isEditorPaused } from "../core";

export type AppearKind = "fade" | "scale" | "rise";

export interface AppearParams {
  /** fade = fade in, scale = grow from nothing, rise = slide up while fading in. */
  kind: AppearKind;
  /** How long the entrance takes, in seconds. */
  duration: number;
  /** For "rise": how far below its place the object starts, in pixels. */
  distance: number;
}

/**
 * Plays a one-off entrance animation when the game starts. In Edit mode the object shows its final
 * state, so you can position it normally.
 */
export class Appear extends Component<AppearParams> {
  static readonly componentName = "Appear";
  static readonly defaults: AppearParams = {
    kind: "fade",
    duration: 0.4,
    distance: 24,
  };

  private elapsed = 0;
  private playing = false;
  private base = { alpha: 1, scaleX: 1, scaleY: 1, y: 0 };

  attach(): void {
    const t = this.target;
    this.base = {
      alpha: t.alpha,
      scaleX: t.scale.x,
      scaleY: t.scale.y,
      y: t.y,
    };
  }

  apply(): void {
    // Restart the entrance whenever params change; the final state is shown in the editor.
    this.elapsed = 0;
    this.playing = true;
    if (isEditorPaused()) this.show(1);
  }

  update(): void {
    if (isEditorPaused()) {
      this.show(1);
      return;
    }
    if (!this.playing) return;
    this.elapsed += Ticker.shared.deltaMS / 1000;
    const duration = this.params.duration > 0 ? this.params.duration : 0.0001;
    const p = Math.min(1, this.elapsed / duration);
    this.show(1 - Math.pow(1 - p, 3)); // ease-out cubic
    if (p >= 1) this.playing = false;
  }

  detach(): void {
    this.show(1);
  }

  /** Shows the object at progress `p` (0 = hidden/start, 1 = final), from its captured base. */
  private show(p: number): void {
    const t = this.target;
    const b = this.base;
    t.alpha = b.alpha;
    t.scale.set(b.scaleX, b.scaleY);
    t.y = b.y;
    if (this.params.kind === "scale") {
      t.scale.set(b.scaleX * p, b.scaleY * p);
    } else if (this.params.kind === "rise") {
      t.y = b.y + (1 - p) * this.params.distance;
      t.alpha = b.alpha * p;
    } else {
      t.alpha = b.alpha * p;
    }
  }
}
